SELECT "name", ROUND(AVG("salary"),2) AS "average salary" FROM "performances" JOIN "salaries" ON "salaries"."player_id" = "performances"."player_id" AND "salaries"."year" = "performances"."year" AND "salaries"."team_id" = "performances"."team_id" JOIN "teams" ON "teams"."id" = "performances"."team_id" WHERE "salaries"."year" = 2001  GROUP BY "teams"."id" ORDER BY AVG("salary") LIMIT 5;
